schema.content:
Table "atom" {
  "atom_id" TEXT [pk, not null]
  "molecule_id" TEXT
  "element" TEXT
}

Table "bond" {
  "bond_id" TEXT [pk, not null]
  "molecule_id" TEXT
  "bond_type" TEXT
}

Table "connected" {
  "atom_id" TEXT [pk, not null]
  "atom_id2" TEXT [pk, not null]
  "bond_id" TEXT
}

Table "molecule" {
  "molecule_id" TEXT [pk, not null]
  "label" TEXT
}



Ref: "atom"."molecule_id" > "molecule"."molecule_id"

Ref: "bond"."molecule_id" > "molecule"."molecule_id"

Ref: "connected"."bond_id" > "bond"."bond_id"

Ref: "connected"."atom_id2" > "atom"."atom_id"

Ref: "connected"."atom_id" > "atom"."atom_id"
